rdata.rewardRate = uint216(_amount / DURATION);
} else {
uint256 remaining = uint256(rdata.periodFinish) - block.timestamp;
uint256 leftover = remaining * rdata.rewardRate;
rdata.rewardRate = uint216((_amount + leftover) / DURATION);
}

